{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.0) to account for risk aversion or market cooling.",
    "Reduce forecast overshoots (especially after spikes) by 5–10% in the immediate 5–7 day horizon to prevent overreaction.",
    "Apply mean reversion bias: if forecast deviates > ±10% from recent 7-day average, adjust toward that average with decay factor of 0.8 per day.",
    "For 30-day horizons, penalize over-optimistic forecasts (e.g., > +15% above recent high) by subtracting 2–3% of the forecasted value.",
    "If sentiment shows positive momentum (e.g., > 0.5) and forecast is below recent low, increase forecast by 3–5% to reflect bullish sentiment.",
    "Lag correction: if true outcome is significantly lower than forecast 3–5 days prior, reduce subsequent forecasts by 2–4% to account for delayed market reaction."
  ]
}
